## 2. Fix the shared backend state, not the browser isolation

`storageState` creates separate browser sessions; it **does not clone the account’s server-side language setting**.

Use **one picker account per parallel worker**, with **disjoint account pools across CI machines**. Reset language before every test because a worker reuses its account across tests.

```ts
// fixtures.ts
import {
  test as base,
  expect,
  type BrowserContext,
} from '@playwright/test';

type Account = { username: string; password: string };
type State = Awaited<ReturnType<BrowserContext['storageState']>>;

// Each CI machine supplies its OWN disjoint pool of picker accounts.
// Supply credentials through CI secrets, not committed files.
const accounts: Account[] = JSON.parse(
  process.env.PICKER_ACCOUNTS_JSON ?? '[]',
);

export const test = base.extend<{}, { workerState: State }>({
  workerState: [
    async ({ browser }, use, workerInfo) => {
      // Stable across worker restarts; unlike workerIndex.
      const account = accounts[workerInfo.parallelIndex];
      if (!account) {
        throw new Error('Provide at least one picker account per worker');
      }

      const context = await browser.newContext({ storageState: undefined });
      try {
        const page = await context.newPage();
        await page.goto(`${workerInfo.project.use.baseURL}/login`);
        await page.getByLabel('Username').fill(account.username);
        await page.getByLabel('Password').fill(account.password);
        await page.getByRole('button', { name: 'Sign in' }).click();
        await expect(page.getByTestId('signed-in-user')).toBeVisible();

        await use(await context.storageState());
      } finally {
        await context.close();
      }
    },
    { scope: 'worker' },
  ],

  storageState: async ({ workerState }, use) => {
    await use(workerState);
  },
});

export { expect };
```

